+    }
+
+    form {
+      display: grid;
+      gap: 18px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid rgba(159, 208, 255, 0.16);
+      border-radius: 16px;
+      background: rgba(8, 14, 26, 0.36);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    .checkbox-row input[type="checkbox"] {
+      width: 1.1rem;
+      height: 1.1rem;
+      margin-top: 0.2rem;
+      accent-color: var(--accent);
+      flex: none;
+    }
+
+    .checkbox-row label {
+      color: var(--text);
+      line-height: 1.45;
+      cursor: pointer;
+    }
+
+    .required-mark {
+      color: var(--accent-strong);
+      font-weight: 700;
+    }
+
+    .help-text {
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.45;
