+      font-weight: 700;
+      color: #07101d;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      cursor: pointer;
+      justify-self: start;
+      box-shadow: 0 12px 24px rgba(124, 183, 255, 0.22);
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    button:focus-visible,
+    input:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    [hidden] {
+      display: none !important;
+    }
+
+    @media (max-width: 420px) {
+      .card {
+        padding: 22px;
+      }
+
+      .checkbox-row {
+        gap: 10px;
+      }
+
+      button {
+        width: 100%;
+        justify-self: stretch;
+        text-align: center;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
