+      <p class="lede">Please confirm that you agree before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="agree-terms"
+              name="agreeTerms"
+              type="checkbox"
+              required
+              aria-describedby="agree-help agree-error"
+            >
+            <label for="agree-terms">
+              I agree to the terms of use <span class="required-mark" aria-hidden="true">*</span>
+            </label>
+          </div>
+          <p id="agree-help" class="help-text">This is required to proceed.</p>
+          <p id="agree-error" class="error-text" hidden>Error: You must agree to the terms of use.</p>
+        </div>
+
+        <button type="submit">Continue</button>
+        <p id="form-status" class="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('agree-terms');
+    const error = document.getElementById('agree-error');
+    const status = document.getElementById('form-status');
+
+    function setErrorState(isInvalid) {
+      checkbox.setAttribute('aria-invalid', String(isInvalid));
+      error.hidden = !isInvalid;
+      if (isInvalid) {
+        checkbox.setCustomValidity('Please agree to the terms of use.');
+      } else {
+        checkbox.setCustomValidity('');
+      }
+    }
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        setErrorState(false);
+        status.textContent = '';
+      }
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        setErrorState(true);
+        status.textContent = '';
+        checkbox.focus();
+        return;
+      }
+
+      setErrorState(false);
+      status.textContent = 'Thanks — your consent has been recorded.';
+    });
+  </script>
+</body>
+</html>
*** End Patch
